CropNonEmptyMaskIfExistsRectangle make_crop_non_empty_mask_if_exists_rectangle(const ImageMaskView& source,const CropNonEmptyMaskIfExistsConfig& c){
  if(source.image.memory==MemorySpace::Device||(source.mask.valid()&&source.mask.memory==MemorySpace::Device)) throw std::invalid_argument("CUDA mask selection requires crop_non_empty_mask_if_exists");
  return choose_crop_host(source,c);
}
void crop_non_empty_mask_if_exists(const ImageMaskView& source,const MutableImageMaskView& destination,const CropNonEmptyMaskIfExistsConfig& c,cudaStream_t stream){
  if(!source.image.valid()||!destination.image.valid()||source.image.type!=DataType::UInt8||destination.image.type!=DataType::UInt8||source.image.layout!=Layout::HWC||destination.image.layout!=Layout::HWC||!source.image.contiguous()||!destination.image.contiguous()||source.image.memory!=MemorySpace::Device||destination.image.memory!=MemorySpace::Device) throw std::invalid_argument("CropNonEmptyMaskIfExists CUDA image views must be contiguous device HWC uint8");
  if(c.input_width>0&&c.input_width!=source.image.width||c.input_height>0&&c.input_height!=source.image.height||c.channels>0&&c.channels!=source.image.channels||destination.image.width!=c.crop_width||destination.image.height!=c.crop_height) throw std::invalid_argument("CropNonEmptyMaskIfExists image dimensions mismatch");
  if(source.mask.valid()&&(!destination.mask.valid()||source.mask.type!=DataType::UInt8||destination.mask.type!=DataType::UInt8||source.mask.layout!=Layout::HWC||destination.mask.layout!=Layout::HWC||!source.mask.contiguous()||!destination.mask.contiguous()||source.mask.memory!=MemorySpace::Device||destination.mask.memory!=MemorySpace::Device||source.mask.width!=source.image.width||source.mask.height!=source.image.height||destination.mask.width!=c.crop_width||destination.mask.height!=c.crop_height||destination.mask.channels!=source.mask.channels)) throw std::invalid_argument("CropNonEmptyMaskIfExists CUDA mask views mismatch");
  std::vector<std::uint8_t> host_mask; ImageMaskView selection_source=source;
  if(source.mask.valid()){
    host_mask.resize(static_cast<std::size_t>(source.mask.width)*source.mask.height*source.mask.channels);
    check(cudaMemcpyAsync(host_mask.data(),source.mask.data,host_mask.size(),cudaMemcpyDeviceToHost,stream),"cudaMemcpy CropNonEmptyMaskIfExists mask"); check(cudaStreamSynchronize(stream),"cudaStreamSynchronize CropNonEmptyMaskIfExists selection");
    selection_source.mask=make_hwc_u8_view(static_cast<const std::uint8_t*>(host_mask.data()),source.mask.width,source.mask.height,source.mask.channels,MemorySpace::Host);
  }
  const auto r=choose_crop_host(selection_source,c); const int n=std::max(c.crop_width*c.crop_height*c.channels,c.crop_width*c.crop_height*(source.mask.valid()?source.mask.channels:0));
  crop_non_empty_mask_kernel<<<(n+255)/256,256,0,stream>>>(static_cast<const std::uint8_t*>(source.image.data),source.mask.valid()?static_cast<const std::uint8_t*>(source.mask.data):nullptr,static_cast<std::uint8_t*>(destination.image.data),source.mask.valid()?static_cast<std::uint8_t*>(destination.mask.data):nullptr,c,r.x,r.y); check(cudaGetLastError(),"crop_non_empty_mask_if_exists_kernel");
}
void crop_non_empty_mask_if_exists_u8(const std::uint8_t* image,const std::uint8_t* mask,std::uint8_t* output_image,std::uint8_t* output_mask,const CropNonEmptyMaskIfExistsConfig& c,cudaStream_t stream){
  if(!image||!output_image||(mask&&!output_mask)) throw std::invalid_argument("null CropNonEmptyMaskIfExists buffer");
  if(c.input_width<=0||c.input_height<=0||c.channels<=0||c.mask_channels<=0) throw std::invalid_argument("invalid CropNonEmptyMaskIfExists dimensions");
  const auto image_in=make_hwc_u8_view(image,c.input_width,c.input_height,c.channels,MemorySpace::Device); const auto image_out=make_hwc_u8_view(output_image,c.crop_width,c.crop_height,c.channels,MemorySpace::Device);
  ImageMaskView source{image_in,mask?make_hwc_u8_view(mask,c.input_width,c.input_height,c.mask_channels,MemorySpace::Device):ImageView{}}; MutableImageMaskView destination{image_out,mask?make_hwc_u8_view(output_mask,c.crop_width,c.crop_height,c.mask_channels,MemorySpace::Device):MutableImageView{}};
  crop_non_empty_mask_if_exists(source,destination,c,stream);
}
void square_symmetric_pad_u8(const std::uint8_t* in,std::uint8_t* out,const PadConfig& c,cudaStream_t s){if(c.output_width!=c.output_height||c.output_width<max(c.input_width,c.input_height))throw std::invalid_argument("invalid square symmetric pad configuration");pad_to_size_u8(in,out,c,s);}
