void validate_anchor_cuda(SizeAnchor a){if(a!=SizeAnchor::TopLeft&&a!=SizeAnchor::Center)throw std::invalid_argument("invalid size anchor");}
void validate_rounding_cuda(SizeRounding r){if(r!=SizeRounding::Floor&&r!=SizeRounding::Ceil&&r!=SizeRounding::Nearest)throw std::invalid_argument("invalid size rounding");}
int rounded_cuda(double x,SizeRounding r){if(!std::isfinite(x)||x<1||x>std::numeric_limits<int>::max())throw std::invalid_argument("size target is outside integer range");if(r==SizeRounding::Floor)return static_cast<int>(floor(x));if(r==SizeRounding::Ceil)return static_cast<int>(ceil(x));if(r==SizeRounding::Nearest)return static_cast<int>(floor(x+.5));throw std::invalid_argument("invalid size rounding");}
int multiple_cuda(int n,int m,bool pad){if(n<=0||m<=0)throw std::invalid_argument("size dimensions and multiples must be positive");long long q=pad?(static_cast<long long>(n)+m-1)/m:n/m;if(q<1||q*m>std::numeric_limits<int>::max())throw std::invalid_argument("multiple target overflows");return static_cast<int>(q*m);}
int power_cuda(int n,int b,bool pad){if(n<=0||b<2)throw std::invalid_argument("size dimensions and power base are invalid");long long p=1;while(p<n){if(p>std::numeric_limits<int>::max()/b)throw std::invalid_argument("power target overflows");p*=b;}if(!pad&&p>n)p/=b;return static_cast<int>(p);}
SizeTransformDimensions aspect_cuda(const AspectRatioConfig& c,bool pad){valid(c.input_width,c.input_height,c.channels);if(!std::isfinite(c.aspect_ratio)||c.aspect_ratio<=0)throw std::invalid_argument("aspect ratio must be finite and positive");validate_anchor_cuda(c.anchor);validate_rounding_cuda(c.rounding);const double current=static_cast<double>(c.input_width)/c.input_height;int w=c.input_width,h=c.input_height;if((pad&&current<c.aspect_ratio)||(!pad&&current>c.aspect_ratio))w=rounded_cuda(static_cast<double>(c.input_height)*c.aspect_ratio,c.rounding);else if((pad&&current>c.aspect_ratio)||(!pad&&current<c.aspect_ratio))h=rounded_cuda(static_cast<double>(c.input_width)/c.aspect_ratio,c.rounding);if(pad){w=max(w,c.input_width);h=max(h,c.input_height);}else{w=min(w,c.input_width);h=min(h,c.input_height);}return {w,h};}
void launch_size(const std::uint8_t* i,std::uint8_t* o,int iw,int ih,int c,int ow,int oh,std::uint8_t value,PadBorder border,SizeAnchor anchor,bool pad,cudaStream_t s){valid(iw,ih,c);if(!i||!o||ow<=0||oh<=0||static_cast<int>(border)<0||static_cast<int>(border)>2||((pad&&(ow<iw||oh<ih))||(!pad&&(ow>iw||oh>ih))))throw std::invalid_argument("invalid size transform configuration");const int n=ow*oh*c;size_transform_kernel<<<(n+255)/256,256,0,s>>>(i,o,iw,ih,ow,oh,c,value,border,anchor,pad);check(cudaGetLastError(),"size_transform_kernel");}
}
SizeTransformDimensions make_pad_to_multiples_of_dimensions(const MultiplesOfConfig& c){valid(c.input_width,c.input_height,c.channels);validate_anchor_cuda(c.anchor);return {multiple_cuda(c.input_width,c.multiple_width,true),multiple_cuda(c.input_height,c.multiple_height,true)};}
