void keep_size_by_resize_u8(const std::uint8_t* i,std::uint8_t* o,const KeepSizeByResizeConfig& c,cudaStream_t s){valid(c.input_width,c.input_height,c.channels);if(!i||!o||c.intermediate_width<=0||c.intermediate_height<=0||static_cast<int>(c.interpolation)<0||static_cast<int>(c.interpolation)>2)throw std::invalid_argument("invalid KeepSizeByResize configuration");if(c.intermediate_width==c.input_width&&c.intermediate_height==c.input_height){check(cudaMemcpyAsync(o,i,static_cast<std::size_t>(c.input_width)*c.input_height*c.channels,cudaMemcpyDeviceToDevice,s),"cudaMemcpy KeepSizeByResize");return;}const std::size_t bytes=static_cast<std::size_t>(c.intermediate_width)*c.intermediate_height*c.channels;std::uint8_t* tmp=nullptr;check(cudaMalloc(&tmp,bytes),"cudaMalloc KeepSizeByResize");try{resize_u8(i,tmp,{c.input_width,c.input_height,c.intermediate_width,c.intermediate_height,c.channels,c.interpolation},s);resize_u8(tmp,o,{c.intermediate_width,c.intermediate_height,c.input_width,c.input_height,c.channels,c.interpolation},s);check(cudaFree(tmp),"cudaFree KeepSizeByResize");}catch(...){cudaFree(tmp);throw;}}
